<section class="pm-panel"><div class="pm-panel-head"><div><p class="pm-eyebrow">DELIVERY TIMELINE</p><h2>Release phases</h2></div><span class="pm-muted">{{ $release->planned_deploy_date?->isPast() ? 'Past target' : $release->planned_deploy_date?->diffInDays(today()).' days to deployment' }}</span></div>
<div class="pm-release-phases">@if($release->globalCycle)
@foreach($release->globalCycle->stages as $stage)
<div class="pm-release-phase"><div class="pm-release-phase-top"><strong>{{ $stage->name }}</strong><span class="pm-pill">{{ $stage->completion_percent===100 ? 'Complete' : ($stage->end_date->isPast() ? 'Overdue' : 'In plan') }}</span></div><small>{{ $stage->start_date->format('d M') }} → {{ $stage->end_date->format('d M Y') }}</small><div class="pm-progress" aria-label="{{ $stage->completion_percent }} percent complete"><i style="width:{{ $stage->completion_percent }}%"></i></div><small>{{ $stage->completion_percent }}% complete</small></div>
@endforeach
@else @foreach($release->cycle?->phases ?? [] as $phase)
@php($totalDays=max(1,$phase->planned_start_date->diffInDays($phase->planned_end_date)))
@php($elapsedDays=$phase->planned_start_date->isFuture() ? 0 : min($totalDays,$phase->planned_start_date->diffInDays(today())))
@php($phasePct=round($elapsedDays/$totalDays*100))
<div class="pm-release-phase"><div class="pm-release-phase-top"><strong>{{ ucwords(str_replace('_', ' ', $phase->phase_key)) }}</strong><span class="pm-pill">{{ $phase->signed_off ? 'Signed off' : 'Pending' }}</span></div><small>{{ $phase->planned_start_date?->format('d M') }} → {{ $phase->planned_end_date?->format('d M Y') }}</small><div class="pm-progress" aria-label="{{ $phasePct }} percent of planned schedule elapsed"><i style="width:{{ $phasePct }}%"></i></div><small>{{ $phasePct }}% of scheduled time elapsed</small></div>@endforeach @endif</div>
</section>
<section class="pm-panel"><div class="pm-panel-head"><h2>Filter release scope</h2><span class="pm-muted">{{ $visibleTickets->count() }} of {{ $release->tickets->count() }} tickets shown</span></div><form method="get" class="pm-toolbar pm-filterbar"><select name="category" aria-label="Category"><option value="">All categories</option>@foreach(\App\Http\Controllers\Pms\TicketController::CATEGORIES as $key => $label)<option value="{{ $key }}" @selected(request('category') === $key)>{{ $key }} · {{ $label }}</option>@endforeach</select><select name="status" aria-label="Status"><option value="">All statuses</option>@foreach($release->tickets->pluck('status')->unique()->sort() as $status)<option @selected(request('status') === $status)>{{ $status }}</option>@endforeach</select><select name="priority" aria-label="Priority"><option value="">Any priority</option>@foreach(\App\Support\PmsPriority::OPTIONS as $priority=>$label)<option value="{{ $priority }}" @selected(request('priority') === $priority)>{{ $label }}</option>@endforeach</select><select name="assignee" aria-label="Developer"><option value="">All developers</option>@foreach($release->project->members as $member)<option value="{{ $member->id }}" @selected(request('assignee') == $member->id)>{{ $member->name }}</option>@endforeach</select><button class="pm-button secondary">Apply</button><a href="{{ route('pms.releases.show', $release) }}">Clear</a></form></section>
